(function(){'use strict';var MEDIA_EXT=/\.(jpg|jpeg|png|gif|webp|svg|mp4|webm|ogg|mp3|pdf|zip)(\?|$)/i;var LIGHTBOX_SEL='[data-fancybox],[data-elementor-open-lightbox],[data-lightbox],.woodmart-hover-base a[data-src],.wd-gallery-item a';var GALLERY_SEL='.gallery,.wp-block-gallery,.woocommerce-product-gallery,.elementor-widget-image-gallery';var IGNORE_LINK_CLASS='.no-swup,[data-no-swup]';function pathOnly(href){try{return new URL(href,window.location.origin).pathname}catch(e){return href||''}}function shouldIgnoreVisit(url,el){if(!el)return false;var href=el.getAttribute('href')||url||'';if(/^(mailto:|tel:|sms:|javascript:|blob:|data:)/i.test(href))return true;if(MEDIA_EXT.test(pathOnly(href)))return true;if(el.closest(LIGHTBOX_SEL))return true;if(el.matches&&el.matches(IGNORE_LINK_CLASS))return true;var gallery=el.closest(GALLERY_SEL);if(gallery&&MEDIA_EXT.test(pathOnly(href)))return true;if(/add-to-cart=|remove_item=|undo_item|update_cart|apply_coupon|wc-ajax=/.test(href))return true;if(el.closest('.ajax_add_to_cart, .add_to_cart_button, .remove_from_cart_button, .single_add_to_cart_button'))return true;try{var u=new URL(href,window.location.origin);if(u.origin!==window.location.origin)return true;var p=u.pathname.toLowerCase();if(p.indexOf('/wp-admin')!==-1)return true;if(p.indexOf('/wp-login')!==-1)return true;if(p.indexOf('/wp-json')!==-1)return true;if(u.search.indexOf('customer-logout')!==-1)return true;if(/\/(checkout|order-pay|order-received)(\/|$)/i.test(p))return true}catch(e){return true}return false}function isEditorContext(){try{if(document.body&&document.body.classList.contains('elementor-editor-active'))return true;if(window.elementorFrontend&&window.elementorFrontend.isEditMode&&window.elementorFrontend.isEditMode())return true}catch(e){}return false}function bindCompat(){if(!window.SLL||!window.SLL.swup)return false;var swup=window.SLL.swup;if(swup._sllCompatBound)return true;swup._sllCompatBound=true;var prev=swup.options&&swup.options.ignoreVisit;swup.options.ignoreVisit=function(url,args){var el=args&&args.el;if(shouldIgnoreVisit(url,el))return true;if(typeof prev==='function'&&prev(url,args))return true;return false};if(isEditorContext()&&typeof swup.destroy==='function'){try{swup.destroy()}catch(e){}}window.SLL.shouldIgnoreVisit=shouldIgnoreVisit;return true}function boot(){if(bindCompat())return;document.addEventListener('sll:ready',bindCompat);setTimeout(bindCompat,500);setTimeout(bindCompat,1500)}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',boot)}else{boot()}})();
